class Solution { private long mirror(long half,boolean odd){long result=half,rest=odd?half/10:half;while(rest>0){result=result*10+rest%10;rest/=10;}return result;}private long cost(int[] nums,long target){long total=0;for(int value:nums)total+=Math.abs((long)value-target);return total;}public long minimumCost(int[] nums){Arrays.sort(nums);long median=nums[nums.length/2];String text=Long.toString(median);int length=text.length(),halfLength=(length+1)/2;long prefix=Long.parseLong(text.substring(0,halfLength));Set<Long> candidates=new HashSet<>();candidates.add(1L);candidates.add(999_999_999L);long power=1;for(int i=0;i<length;i++)power*=10;candidates.add(power/10-1);candidates.add(power+1);for(int delta=-1;delta<=1;delta++){long half=prefix+delta;if(half>0)candidates.add(mirror(half,(length&1)==1));}long answer=Long.MAX_VALUE;for(long candidate:candidates)if(candidate>=1&&candidate<1_000_000_000L)answer=Math.min(answer,cost(nums,candidate));return answer;} }
